SET NOCOUNT ON;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaMigrationHistory WHERE MigrationId=N'0059_stage2_route_dispatch_notifications' AND FileName=N'0059_stage2_route_dispatch_notifications.sql' AND Status=N'Applied' AND FileSha256=UPPER(N'$(MigrationSha256)')) THROW 59520,N'0059 ledger mismatch.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaMigrationHistory WHERE MigrationId=N'0058_stage2_delivery_notifications' AND Status=N'Applied' AND FileSha256=N'30DD0D7ACEDE56D067CA6A583C02692D071619017987A5D1E0ECF6B98FF38D63') THROW 59520,N'0058 prerequisite differs.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'dbo.sp_Rutas_Dispatch')))),0x)<>0xEC93FA51F9F94E578D774CE8A4B2F54875872097BC73F3D6CD74633EFC63D00E THROW 59520,N'Historical dispatch definition differs.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'dbo.sp_Stage2_RequireOriginalLogin')))),0x)<>0x8C8515B2D2DD516A737A548EE7A03AB3E12D101BB8D6B27A1FBDC8846E31479C THROW 59520,N'Original-login guard differs.',1;
IF NOT EXISTS(SELECT 1 FROM sys.schemas WHERE name=N'RouteDispatch' AND principal_id=USER_ID(N'dbo')) THROW 59520,N'RouteDispatch schema ownership differs.',1;
IF OBJECT_ID(N'RouteDispatch.Dispatches',N'U') IS NULL OR OBJECT_ID(N'RouteDispatch.Items',N'U') IS NULL OR OBJECT_ID(N'RouteDispatch.Requests',N'U') IS NULL OR OBJECT_ID(N'RouteDispatch.Attempts',N'U') IS NULL OR OBJECT_ID(N'RouteDispatch.Events',N'U') IS NULL THROW 59520,N'RouteDispatch tables missing.',1;
IF OBJECT_ID(N'RouteDispatch.Dispatch',N'P') IS NULL OR OBJECT_ID(N'RouteDispatch.GetOwned',N'P') IS NULL OR OBJECT_ID(N'RouteDispatch.Request',N'P') IS NULL OR OBJECT_ID(N'RouteDispatch.Claim',N'P') IS NULL OR OBJECT_ID(N'RouteDispatch.Complete',N'P') IS NULL OR OBJECT_ID(N'RouteDispatch.Receipt',N'P') IS NULL THROW 59520,N'Public RouteDispatch procedures missing.',1;
IF (SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'RouteDispatch.Dispatch'))<>10 OR (SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'RouteDispatch.GetOwned'))<>9 OR (SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'RouteDispatch.Request'))<>12 OR (SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'RouteDispatch.Claim'))<>13 OR (SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'RouteDispatch.Complete'))<>3 OR (SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'RouteDispatch.Receipt'))<>12 THROW 59520,N'Public procedure signatures differ.',1;
IF COL_LENGTH(N'RouteDispatch.Dispatches',N'DispatchId')<>16 OR COL_LENGTH(N'RouteDispatch.Dispatches',N'RutaId')<>4 OR COL_LENGTH(N'RouteDispatch.Dispatches',N'OriginalLoginId')<>16 OR COL_LENGTH(N'RouteDispatch.Dispatches',N'Actor')<>4 OR COL_LENGTH(N'RouteDispatch.Dispatches',N'CreatedUtc')<>8 THROW 59520,N'Dispatch ownership columns differ.',1;
IF COL_LENGTH(N'RouteDispatch.Items',N'EventId')<>8 OR COL_LENGTH(N'RouteDispatch.Items',N'EventGuid')<>16 OR COL_LENGTH(N'RouteDispatch.Items',N'DispatchId')<>16 OR COL_LENGTH(N'RouteDispatch.Items',N'RutaPedidoId')<>4 OR COL_LENGTH(N'RouteDispatch.Items',N'PedidoId')<>4 OR COL_LENGTH(N'RouteDispatch.Items',N'CustomerId')<>4 OR COL_LENGTH(N'RouteDispatch.Items',N'CustomerName')<>300 OR COL_LENGTH(N'RouteDispatch.Items',N'CustomerEmail')<>300 OR COL_LENGTH(N'RouteDispatch.Items',N'NotifyEligible')<>1 OR COL_LENGTH(N'RouteDispatch.Items',N'RecordedUtc')<>8 THROW 59520,N'Immutable dispatch snapshot columns differ.',1;
IF COL_LENGTH(N'RouteDispatch.Requests',N'OperationId')<>16 OR COL_LENGTH(N'RouteDispatch.Requests',N'EventId')<>8 OR COL_LENGTH(N'RouteDispatch.Requests',N'OriginalLoginId')<>16 OR COL_LENGTH(N'RouteDispatch.Requests',N'Actor')<>4 OR COL_LENGTH(N'RouteDispatch.Requests',N'SourceHash')<>32 THROW 59520,N'Notification ownership columns differ.',1;
DECLARE @Columns table(T sysname,C sysname,Ty sysname,L smallint,N bit,S tinyint,I bit);
INSERT @Columns VALUES
 (N'Dispatches',N'DispatchId',N'uniqueidentifier',16,0,0,0),(N'Dispatches',N'RutaId',N'int',4,0,0,0),(N'Dispatches',N'OriginalLoginId',N'uniqueidentifier',16,0,0,0),(N'Dispatches',N'Actor',N'int',4,0,0,0),(N'Dispatches',N'CreatedUtc',N'datetime2',8,0,7,0),
 (N'Items',N'EventId',N'bigint',8,0,0,1),(N'Items',N'EventGuid',N'uniqueidentifier',16,0,0,0),(N'Items',N'DispatchId',N'uniqueidentifier',16,0,0,0),(N'Items',N'RutaPedidoId',N'int',4,0,0,0),(N'Items',N'PedidoId',N'int',4,0,0,0),(N'Items',N'CustomerId',N'int',4,0,0,0),(N'Items',N'CustomerName',N'nvarchar',300,0,0,0),(N'Items',N'CustomerEmail',N'nvarchar',300,1,0,0),(N'Items',N'NotifyEligible',N'bit',1,0,0,0),(N'Items',N'RecordedUtc',N'datetime2',8,0,7,0),
 (N'Requests',N'OperationId',N'uniqueidentifier',16,0,0,0),(N'Requests',N'EventId',N'bigint',8,0,0,0),(N'Requests',N'OriginalLoginId',N'uniqueidentifier',16,0,0,0),(N'Requests',N'Actor',N'int',4,0,0,0),(N'Requests',N'SourceHash',N'binary',32,0,0,0),(N'Requests',N'CreatedUtc',N'datetime2',8,0,7,0),
 (N'Attempts',N'OperationId',N'uniqueidentifier',16,0,0,0),(N'Attempts',N'State',N'nvarchar',40,0,0,0),(N'Attempts',N'ClaimHash',N'binary',32,1,0,0),(N'Attempts',N'AttemptedUtc',N'datetime2',8,1,7,0),(N'Attempts',N'CompletedUtc',N'datetime2',8,1,7,0),
 (N'Events',N'AuditId',N'bigint',8,0,0,1),(N'Events',N'OperationId',N'uniqueidentifier',16,0,0,0),(N'Events',N'State',N'nvarchar',40,0,0,0),(N'Events',N'CreatedUtc',N'datetime2',8,0,7,0);
IF EXISTS(SELECT 1 FROM @Columns e LEFT JOIN sys.columns c ON c.object_id=OBJECT_ID(N'RouteDispatch.'+e.T) AND c.name=e.C WHERE c.object_id IS NULL OR TYPE_NAME(c.user_type_id)<>e.Ty OR c.max_length<>e.L OR c.is_nullable<>e.N OR c.scale<>e.S OR c.is_identity<>e.I)
 OR (SELECT COUNT(*) FROM sys.columns WHERE object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')))<>(SELECT COUNT(*) FROM @Columns)
 OR (SELECT COUNT(*) FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch'))<>5 THROW 59520,N'RouteDispatch table contract differs.',1;
DECLARE @Indexes table(T sysname,N sysname,U bit,P bit,K nvarchar(500),Included int);
INSERT @Indexes VALUES
 (N'Dispatches',N'PK_RouteDispatch_Dispatches',1,1,N'DispatchId',0),(N'Dispatches',N'UQ_RouteDispatch_Dispatch_Route',1,0,N'RutaId',0),(N'Dispatches',N'IX_RouteDispatch_Owner',0,0,N'OriginalLoginId,Actor,RutaId,CreatedUtc',0),
 (N'Items',N'PK_RouteDispatch_Items',1,1,N'EventId',0),(N'Items',N'UQ_RouteDispatch_EventGuid',1,0,N'EventGuid',0),(N'Items',N'UQ_RouteDispatch_RouteOrder',1,0,N'RutaPedidoId',0),(N'Items',N'IX_RouteDispatch_Items_Dispatch',0,0,N'DispatchId,EventId',0),
 (N'Requests',N'PK_RouteDispatch_Requests',1,1,N'OperationId',0),(N'Requests',N'UQ_RouteDispatch_Request_Event',1,0,N'EventId',0),(N'Attempts',N'PK_RouteDispatch_Attempts',1,1,N'OperationId',0),(N'Events',N'PK_RouteDispatch_Events',1,1,N'AuditId',0);
DECLARE @ActualIndexes table(T sysname,N sysname,U bit,P bit,K nvarchar(500),Included int);
INSERT @ActualIndexes
SELECT OBJECT_NAME(i.object_id),i.name,i.is_unique,i.is_primary_key,
 STRING_AGG(CASE WHEN ic.is_included_column=0 THEN CONVERT(nvarchar(max),c.name) END,N',') WITHIN GROUP(ORDER BY ic.key_ordinal),
 SUM(CASE WHEN ic.is_included_column=1 THEN 1 ELSE 0 END)
FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id
JOIN sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id
WHERE i.object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')) AND i.index_id>0 AND i.is_disabled=0 AND i.has_filter=0
GROUP BY i.object_id,i.name,i.is_unique,i.is_primary_key;
IF EXISTS(SELECT * FROM @Indexes EXCEPT SELECT * FROM @ActualIndexes) OR EXISTS(SELECT * FROM @ActualIndexes EXCEPT SELECT * FROM @Indexes) THROW 59520,N'RouteDispatch index contract differs.',1;
DECLARE @ForeignKeys table(PT sysname,PC sysname,RT nvarchar(300),RC sysname);
INSERT @ForeignKeys VALUES
 (N'Dispatches',N'RutaId',N'dbo.Rutas',N'RutaId'),(N'Dispatches',N'OriginalLoginId',N'dbo.Stage2OriginalLogins',N'LoginId'),(N'Dispatches',N'Actor',N'dbo.Usuarios',N'UsuarioId'),
 (N'Items',N'DispatchId',N'RouteDispatch.Dispatches',N'DispatchId'),(N'Items',N'RutaPedidoId',N'dbo.RutaPedidos',N'RutaPedidoId'),(N'Items',N'PedidoId',N'dbo.Pedidos',N'PedidoId'),(N'Items',N'CustomerId',N'dbo.Usuarios',N'UsuarioId'),
 (N'Requests',N'EventId',N'RouteDispatch.Items',N'EventId'),(N'Requests',N'OriginalLoginId',N'dbo.Stage2OriginalLogins',N'LoginId'),(N'Requests',N'Actor',N'dbo.Usuarios',N'UsuarioId'),
 (N'Attempts',N'OperationId',N'RouteDispatch.Requests',N'OperationId'),(N'Events',N'OperationId',N'RouteDispatch.Requests',N'OperationId');
DECLARE @ActualForeignKeys table(PT sysname,PC sysname,RT nvarchar(300),RC sysname);
INSERT @ActualForeignKeys
SELECT OBJECT_NAME(f.parent_object_id),pc.name,QUOTENAME(OBJECT_SCHEMA_NAME(f.referenced_object_id))+N'.'+QUOTENAME(OBJECT_NAME(f.referenced_object_id)),rc.name
FROM sys.foreign_keys f JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id
JOIN sys.columns pc ON pc.object_id=f.parent_object_id AND pc.column_id=fc.parent_column_id
JOIN sys.columns rc ON rc.object_id=f.referenced_object_id AND rc.column_id=fc.referenced_column_id
WHERE f.parent_object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')) AND f.is_disabled=0 AND f.is_not_trusted=0
 AND f.delete_referential_action=0 AND f.update_referential_action=0;
UPDATE @ActualForeignKeys SET RT=REPLACE(REPLACE(RT,N'[',N''),N']',N'');
IF EXISTS(SELECT * FROM @ForeignKeys EXCEPT SELECT * FROM @ActualForeignKeys) OR EXISTS(SELECT * FROM @ActualForeignKeys EXCEPT SELECT * FROM @ForeignKeys) THROW 59520,N'RouteDispatch foreign-key contract differs.',1;
IF NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'RouteDispatch.ImmutableDispatches') AND is_disabled=0) OR NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'RouteDispatch.ImmutableItems') AND is_disabled=0) OR NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'RouteDispatch.ImmutableRequests') AND is_disabled=0) OR NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'RouteDispatch.ImmutableEvents') AND is_disabled=0) OR NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N'RouteDispatch.AttemptTransitions') AND is_disabled=0) THROW 59520,N'Immutability/state triggers missing or disabled.',1;
IF (SELECT COUNT(*) FROM sys.foreign_keys WHERE parent_object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')) AND is_disabled=0 AND is_not_trusted=0)<>12
 OR (SELECT COUNT(*) FROM sys.check_constraints WHERE parent_object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')) AND is_disabled=0 AND is_not_trusted=0)<>4
 OR (SELECT COUNT(*) FROM sys.indexes WHERE object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')) AND is_primary_key=1 AND is_disabled=0)<>5
 OR NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'RouteDispatch.Attempts') AND name=N'CK_RouteDispatch_AttemptState' AND parent_column_id=0 AND is_disabled=0 AND is_not_trusted=0)
 THROW 59520,N'RouteDispatch constraints differ.',1;
IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name=N'CK_RouteDispatch_DispatchId' AND parent_object_id=OBJECT_ID(N'RouteDispatch.Dispatches') AND definition LIKE N'%DispatchId%00000000-0000-0000-0000-000000000000%')
 OR NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name=N'CK_RouteDispatch_EventGuid' AND parent_object_id=OBJECT_ID(N'RouteDispatch.Items') AND definition LIKE N'%EventGuid%00000000-0000-0000-0000-000000000000%')
 OR NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name=N'CK_RouteDispatch_OperationId' AND parent_object_id=OBJECT_ID(N'RouteDispatch.Requests') AND definition LIKE N'%OperationId%00000000-0000-0000-0000-000000000000%')
 OR NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name=N'CK_RouteDispatch_AttemptState' AND parent_object_id=OBJECT_ID(N'RouteDispatch.Attempts') AND definition LIKE N'%Pending%' AND definition LIKE N'%Sending%' AND definition LIKE N'%SmtpAccepted%' AND definition LIKE N'%Unknown%' AND definition LIKE N'%ClaimHash%' AND definition LIKE N'%AttemptedUtc%' AND definition LIKE N'%CompletedUtc%')
 THROW 59520,N'RouteDispatch check definitions differ.',1;
DECLARE @Defaults table(T sysname,C sysname,N sysname);
INSERT @Defaults VALUES (N'Dispatches',N'CreatedUtc',N'DF_RouteDispatch_Created'),(N'Items',N'RecordedUtc',N'DF_RouteDispatch_ItemRecorded'),(N'Requests',N'CreatedUtc',N'DF_RouteDispatch_RequestCreated'),(N'Events',N'CreatedUtc',N'DF_RouteDispatch_EventCreated');
IF EXISTS(SELECT 1 FROM @Defaults e LEFT JOIN sys.default_constraints d ON d.parent_object_id=OBJECT_ID(N'RouteDispatch.'+e.T) AND d.name=e.N LEFT JOIN sys.columns c ON c.object_id=d.parent_object_id AND c.column_id=d.parent_column_id WHERE d.object_id IS NULL OR c.name<>e.C OR LOWER(d.definition) NOT LIKE N'%sysutcdatetime%')
 OR (SELECT COUNT(*) FROM sys.default_constraints WHERE parent_object_id IN(SELECT object_id FROM sys.tables WHERE schema_id=SCHEMA_ID(N'RouteDispatch')))<>(SELECT COUNT(*) FROM @Defaults)
 THROW 59520,N'RouteDispatch default contract differs.',1;
IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.sp_Stage2_RouteOperation')) NOT LIKE N'%Use RouteDispatch.Dispatch.%' OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.sp_Stage2_RouteOperation')) LIKE N'%EXEC dbo.sp_Rutas_Dispatch%' THROW 59520,N'Legacy dispatch bypass remains.',1;
IF OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Dispatch')) NOT LIKE N'%INSERT @Recipients EXEC dbo.sp_Rutas_Dispatch%' OR OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Dispatch')) NOT LIKE N'%RUTAS_GESTIONAR%' OR OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.GetOwned')) NOT LIKE N'%OriginalLoginId=@LoginId%' THROW 59520,N'Dispatch ownership/transaction contract differs.',1;
IF OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Claim')) NOT LIKE N'%@@TRANCOUNT<>0%' OR OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Claim')) NOT LIKE N'%COMMIT%' OR OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Complete')) NOT LIKE N'%ClaimHash=HASHBYTES%' THROW 59520,N'Notification claim/complete contract differs.',1;
IF EXISTS(SELECT 1 FROM sys.database_permissions dp JOIN sys.objects o ON o.object_id=dp.major_id WHERE o.schema_id=SCHEMA_ID(N'RouteDispatch') AND dp.state IN('G','W'))
 OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE class=3 AND major_id=SCHEMA_ID(N'RouteDispatch') AND state IN('G','W')) THROW 59520,N'Unexpected explicit grants on RouteDispatch namespace.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'dbo.sp_Stage2_RouteOperation')))),0x)<>0x01D6926AB658F22D1EB30E88A5B17D57691C000E5DC8297BD3A47AE48906C3A2 THROW 59520,N'Route operation wrapper differs.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.AttemptTransitions')))),0x)<>0x660F3800D53FFEB082141BDBDBA87DDDA22EFAD7E8BFEC9C550FFFFC1A6B492F THROW 59520,N'RouteDispatch module differs: AttemptTransitions.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Claim')))),0x)<>0xB0B53FD7ADBC9C596F94661FEF7C3F42AF4DC429B37CDBD38A0FA2DB59A273B7 THROW 59520,N'RouteDispatch module differs: Claim.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Complete')))),0x)<>0xEF256B149EF85C3305B2CBB1D0BB25118BB9695AB55DE70E466FAABCE6D77EA3 THROW 59520,N'RouteDispatch module differs: Complete.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Dispatch')))),0x)<>0x0B918DB729C4E1B05F83D39F15AE522CD54C4803B67871F7D5BFA93D1E6728AD THROW 59520,N'RouteDispatch module differs: Dispatch.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.GetOwned')))),0x)<>0x36719ECCF8B2B46DF73498705D1DD0C289D17E1FC32E63B701F7C0D511156BDA THROW 59520,N'RouteDispatch module differs: GetOwned.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.ImmutableDispatches')))),0x)<>0x02E7ED4EF66454CC246CE52FE8B23D19023E6ACC6E158E11FD97A3936A082B83 THROW 59520,N'RouteDispatch module differs: ImmutableDispatches.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.ImmutableEvents')))),0x)<>0xA9B2FAF95B5B46840366A341859A9C95E68C2D1438660D79ED804AB2E13F7006 THROW 59520,N'RouteDispatch module differs: ImmutableEvents.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.ImmutableItems')))),0x)<>0x1460F685BC632CF279D030E09ACEC3F0D6BE23F4A8D1D8AEAA3F38569E556B14 THROW 59520,N'RouteDispatch module differs: ImmutableItems.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.ImmutableRequests')))),0x)<>0x70AB921C85C7FEAA781F10BC88BF0F2637763E2E7A4848A35BFDCD53DC72EEC4 THROW 59520,N'RouteDispatch module differs: ImmutableRequests.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Receipt')))),0x)<>0x9E5260E81AAEB6EF1DFC2A716A31C27513EF5A952A09E4FD9079CA2DAFC555F1 THROW 59520,N'RouteDispatch module differs: Receipt.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.Request')))),0x)<>0x80A741C036A0D53FBD4DC1ADCB7432CC16718C540509B6A59EF2361E3BA63B0F THROW 59520,N'RouteDispatch module differs: Request.',1;
IF ISNULL(HASHBYTES('SHA2_256',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N'RouteDispatch.SnapshotHash')))),0x)<>0x75A7849AAB1E1BA821AB3F8E17240B3F0731CDF3AE47F76711CCCB50EA46AA00 THROW 59520,N'RouteDispatch module differs: SnapshotHash.',1;
SELECT N'0059 metadata verification passed; runtime authorization, resultsets, transaction behavior, and SMTP delivery require separate restricted integration tests.' AS Verification;
